// A data layer nobody has written a descriptor for. Its types read as a data
// layer and its methods do not say which of them read and which write, which is
// the whole of what is lost.

export declare class Repo<Entity> {
  find(where?: unknown): Promise<Entity[]>;
  persist(entity: Entity): Promise<Entity>;
  drop(id: string): Promise<void>;
}

// A connection typed by the whole schema rather than by one stored thing. This
// is the shape of a query builder's client: the type argument names every table
// at once, and the table a call touches is a string argument to the call.
export declare class SchemaDb<Schema> {
  selectFrom<Name extends keyof Schema>(table: Name): Promise<unknown[]>;
}

// A generic helper of these typings, which names nothing stored: it describes
// the columns of whatever it is handed. A project that puts a base class of its
// own over `Model` parameterises that base with one of these, so the first type
// argument of the base is this helper for every model in the repository and the
// model itself for none of them. It is declared here, in node_modules, which is
// the fact that settles it: this repository does not store a thing the library's
// own typings declare.
export interface AttributesOnly<T> {
  readonly columns: T;
}

export declare class Model<Attributes> {
  findAll(): Promise<Attributes[]>;
}
